"""Tests for subject.build_topic_router_from_contract."""

from subject import build_topic_router_from_contract


def test_single_event_maps_to_model_prefixed_class_name():
    contract_data = {
        "published_events": [
            {
                "event_type": "NodeRegistrationAccepted",
                "topic": "onex.evt.platform.node-registration-accepted.v1",
            }
        ]
    }
    assert build_topic_router_from_contract(contract_data) == {
        "ModelNodeRegistrationAccepted": "onex.evt.platform.node-registration-accepted.v1"
    }


def test_multiple_events_are_all_mapped():
    contract_data = {
        "published_events": [
            {"event_type": "NodeRegistrationAccepted", "topic": "topic.a.v1"},
            {"event_type": "IntrospectionRequested", "topic": "topic.b.v1"},
            {"event_type": "NodeHeartbeat", "topic": "topic.c.v1"},
        ]
    }
    assert build_topic_router_from_contract(contract_data) == {
        "ModelNodeRegistrationAccepted": "topic.a.v1",
        "ModelIntrospectionRequested": "topic.b.v1",
        "ModelNodeHeartbeat": "topic.c.v1",
    }


def test_event_type_with_digits_and_underscores_is_kept_verbatim():
    contract_data = {
        "published_events": [
            {"event_type": "Batch_CompletedV2", "topic": "topic.batch.v2"}
        ]
    }
    assert build_topic_router_from_contract(contract_data) == {
        "ModelBatch_CompletedV2": "topic.batch.v2"
    }


def test_topic_value_is_preserved_exactly():
